<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Landing Page</title></head><body style="font-family:Arial;max-width:760px;margin:30px auto;padding:16px"><a href="/admin/landing-pages">← Back</a><h1>{{ $page->exists?'Edit':'Create' }} Landing Page</h1>@if($errors->any())<ul style="color:red">@foreach($errors->all() as $error)<li>{{ $error }}</li>@endforeach</ul>@endif<form method="post" action="{{ $page->exists?'/admin/landing-pages/'.$page->id:'/admin/landing-pages' }}">@csrf @if($page->exists)@method('PUT')@endif @foreach(['city'=>'City','slug'=>'URL slug','headline'=>'Headline','subheadline'=>'Subheadline','intro'=>'Intro','meta_title'=>'SEO title','meta_description'=>'SEO description','faq_text'=>'FAQs','callout_note'=>'Call-out note'] as $field=>$label)<p><label>{{ $label }}<br>@if(in_array($field,['intro','subheadline','faq_text','meta_description']))<textarea name="{{ $field }}" rows="3" style="width:100%;padding:9px">{{ old($field,$page->$field) }}</textarea>@else<input name="{{ $field }}" value="{{ old($field,$page->$field) }}" style="width:100%;padding:9px">@endif</label></p>@endforeach<p><label><input type="checkbox" name="is_active" value="1" {{ old('is_active',$page->exists?$page->is_active:true)?'checked':'' }}> Page active</label></p><p><label><input type="checkbox" name="indexable" value="1" {{ old('indexable',$page->indexable)?'checked':'' }}> Allow search indexing (only after content review)</label></p><button style="padding:14px 28px">Save Landing Page</button></form></body></html>